from pyvkteamsclient.tracer import tracerfrom pyvkteamsclient.client.base.client import BaseClientfrom pyvkteamsclient.client.decorators import api_version_checkclass IdmProviderMethod(BaseClient):    """    Методы группы 'Авторизация' из https://im-docs.corp.mail.ru/    """    @api_version_check(min_version=117)    @tracer.start_as_current_span("provider.idm_provider_create")    def idm_provider_create(self, token: str) -> dict:        """        Добавить тип аутентификации пользователю        Добавление нового провайдера аутентификации пользователю        :param token: Токен действия        :return: тело ответа сервера        """        return self.post("idm/provider/create", headers={"Authorization": self.token}, data={"token": token})    @api_version_check(min_version=117)    @tracer.start_as_current_span("provider.idm_provider_delete")    def idm_provider_delete(self, token: str) -> dict:        """        Удаление типа аутентификации из аккаунта пользователя        :param token: Токен действия        :return: тело ответа сервера        """        return self.post("idm/provider/delete", headers={"Authorization": self.token}, data={"token": token})    @api_version_check(min_version=117)    @tracer.start_as_current_span("provider.idm_provider_status")    def idm_provider_status(self, token: str) -> dict:        """        Получение списка статусов возможных аутентификаций для пользователя        :param token: Токен действия        :return: тело ответа сервера        """        return self.post("idm/provider/status", headers={"Authorization": self.token}, data={"token": token})    @api_version_check(min_version=117)    @tracer.start_as_current_span("provider.idm_provider_list")    def idm_provider_list(self, email: str) -> dict:        """        Email пользователя по которому определяется доступный список видов аутентификации        :param email: Токен действия        :return: тело ответа сервера        """        return self.post(            "idm/provider/list",            json={                "email": email,            },        )